// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title RoughNetRegistry
/// @notice Walking-skeleton tracer contract for the RoughNet platform.
///         It holds a single mutable note plus simple provenance metadata so the
///         frontend can demonstrate the full read/write loop: read on-chain state,
///         submit a transaction from a self-custodial wallet, and persist the result
///         off-chain (Neon) for the public Register read-model.
/// @dev This is intentionally minimal. The real on-chain Register, ERC-3643 tokens
///      and DvP settlement land in later issues; this only proves the toolchain.
contract RoughNetRegistry {
    /// @notice The most recently written note.
    string public note;

    /// @notice Number of times {setNote} has succeeded.
    uint256 public updateCount;

    /// @notice Address that performed the most recent update.
    address public lastUpdatedBy;

    /// @notice Emitted whenever the note is updated.
    /// @param by The caller that wrote the note.
    /// @param note The new note value.
    /// @param count The post-update value of {updateCount}.
    event NoteUpdated(address indexed by, string note, uint256 indexed count);

    /// @notice Thrown when an empty note is supplied.
    error EmptyNote();

    /// @param initialNote The genesis note set at deployment.
    constructor(string memory initialNote) {
        note = initialNote;
    }

    /// @notice Update the stored note and provenance metadata.
    /// @param newNote The new note; must be non-empty.
    function setNote(string calldata newNote) external {
        if (bytes(newNote).length == 0) revert EmptyNote();

        note = newNote;
        lastUpdatedBy = msg.sender;
        unchecked {
            updateCount += 1;
        }

        emit NoteUpdated(msg.sender, newNote, updateCount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import { ClaimIssuer } from "@onchain-id/solidity/contracts/ClaimIssuer.sol";

/// @title MockKYCClaimIssuer
/// @notice R1 mock standing in for Ctrl Alt's production KYC / claim-issuer service.
///
///         In production, Ctrl Alt performs KYC/AML off-chain and pushes cryptographically
///         signed claims to each Subscriber's ONCHAINID from a claim-issuer it operates
///         (BRD FR1.8/FR1.9). RoughNet does not run that service. For R1 we deploy this
///         **trusted issuer that RoughNet controls**: it is a real ERC-3643 `ClaimIssuer`
///         (ONCHAINID ERC-734/735), registered in the Trusted Issuers Registry exactly as the
///         real one will be, so the on-chain verification path (`IdentityRegistry.isVerified`)
///         is identical. Only the off-chain KYC decision is mocked — the mock KYC endpoint
///         always returns `ok` and signs a claim with this issuer's management key.
///
///         Replacement is an integration swap, not a rewrite: point the Trusted Issuers
///         Registry at Ctrl Alt's claim-issuer address and stop deploying this contract.
///
/// @dev Ctrl Alt integration tracked by issue #11 (`ctrl-alt-integration`). See ADR-0002,
///      ADR-0005, and CLAUDE.md "Mocks & how to replace them".
contract MockKYCClaimIssuer is ClaimIssuer {
    /// @param initialManagementKey The address whose ECDSA signatures this issuer will treat
    ///        as valid claims. The mock KYC backend holds this key and signs KYC claims with it.
    constructor(address initialManagementKey) ClaimIssuer(initialManagementKey) { }
}

