37	        issuer = vm.addr(ISSUER_PK);
38	
39	        // This test contract is the suite owner and the IR/token agent, so it can unpause,
40	        // mint, register and freeze directly.
41	        suite = _deployFullSuite(address(this), address(this), issuer);
42	        token = IToken(suite.token);
43	        ir = IIdentityRegistry(suite.identityRegistry);
