45	        token.unpause();
46	
47	        alice = _provision("alice", ALICE_PK);
48	        bob = _provision("bob", BOB_PK);
49	        carol = vm.addr(CAROL_PK);
50	    }
51	
52	    /// @notice Mirrors the mock KYC flow: create an ONCHAINID for the wallet, attach a
53	    ///         KYC claim signed by the mock issuer, and register it in the Identity Registry.
54	    function _provision(string memory label, uint256 walletPk) internal returns (address wallet) {
55	        wallet = vm.addr(walletPk);
56	        address identity = IIdFactory(suite.idFactory).createIdentity(wallet, label);
57	
58	        bytes memory data = abi.encode(label, "KYC:ok");
59	        // Claim is signed over keccak256(abi.encode(identity, topic, data)), Ethereum-prefixed.
60	        bytes32 dataHash = keccak256(abi.encode(identity, KYC_TOPIC, data));
61	        bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
62	        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);
63	        bytes memory signature = abi.encodePacked(r, s, v);
64	
65	        // addClaim must be called by a key on the identity; the wallet is its management key.
66	        vm.prank(wallet);
67	        IIdentity(identity).addClaim(KYC_TOPIC, 1, suite.claimIssuer, signature, data, "");
