102	    function test_revokeIdentityRegistration_blocksIncomingTransfer() public {
103	        token.mint(alice, 100);
104	        assertTrue(ir.isVerified(bob));
105	
106	        ir.deleteIdentity(bob); // agent action
107	
108	        assertFalse(ir.isVerified(bob));
109	        vm.prank(alice);
110	        vm.expectRevert("Transfer not possible");
111	        token.transfer(bob, 10);
112	    }
113	
114	    /// @notice Issuer revokes the KYC claim itself -> verification fails, transfers blocked.
115	    function test_revokeClaim_blocksIncomingTransfer() public {
116	        token.mint(alice, 100);
