// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import { Test } from "forge-std/Test.sol";
import { TREXSuiteDeployer } from "../script/TREXSuiteDeployer.sol";

import { IToken } from "@tokenysolutions/t-rex/contracts/token/IToken.sol";
import {
    IIdentityRegistry
} from "@tokenysolutions/t-rex/contracts/registry/interface/IIdentityRegistry.sol";
import { IIdFactory } from "@onchain-id/solidity/contracts/factory/IIdFactory.sol";
import { IIdentity } from "@onchain-id/solidity/contracts/interface/IIdentity.sol";
import { IClaimIssuer } from "@onchain-id/solidity/contracts/interface/IClaimIssuer.sol";

/// @notice Acceptance tests for issue #2 — identity, KYC claim & on-chain whitelist.
///         Exercises the real ERC-3643 verification path: only the off-chain KYC decision is
///         mocked (here, by signing claims with the issuer key directly). Covers the issue's
///         testable criteria: whitelisted->whitelisted transfer succeeds, transfer to a
///         non-whitelisted address reverts, and revocation blocks subsequent transfers.
contract IdentitySuiteTest is Test, TREXSuiteDeployer {
    Suite internal suite;
    IToken internal token;
    IIdentityRegistry internal ir;

    // The mock KYC backend's signing key — the management key of the mock claim issuer.
    uint256 internal constant ISSUER_PK = 0xA11CE;
    address internal issuer;

    uint256 internal constant ALICE_PK = 0xA1;
    uint256 internal constant BOB_PK = 0xB0B;
    uint256 internal constant CAROL_PK = 0xCA401;
    address internal alice;
    address internal bob;
    address internal carol; // never passes KYC

    function setUp() public {
        issuer = vm.addr(ISSUER_PK);

        // This test contract is the suite owner and the IR/token agent, so it can unpause,
        // mint, register and freeze directly.
        suite = _deployFullSuite(address(this), address(this), issuer);
        token = IToken(suite.token);
        ir = IIdentityRegistry(suite.identityRegistry);

        token.unpause();

        alice = _provision("alice", ALICE_PK);
        bob = _provision("bob", BOB_PK);
        carol = vm.addr(CAROL_PK);
    }

    /// @notice Mirrors the mock KYC flow: create an ONCHAINID for the wallet, attach a
    ///         KYC claim signed by the mock issuer, and register it in the Identity Registry.
    function _provision(string memory label, uint256 walletPk) internal returns (address wallet) {
        wallet = vm.addr(walletPk);
        address identity = IIdFactory(suite.idFactory).createIdentity(wallet, label);

        bytes memory data = abi.encode(label, "KYC:ok");
        // Claim is signed over keccak256(abi.encode(identity, topic, data)), Ethereum-prefixed.
        bytes32 dataHash = keccak256(abi.encode(identity, KYC_TOPIC, data));
        bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);
        bytes memory signature = abi.encodePacked(r, s, v);

        // addClaim must be called by a key on the identity; the wallet is its management key.
        vm.prank(wallet);
        IIdentity(identity).addClaim(KYC_TOPIC, 1, suite.claimIssuer, signature, data, "");

        ir.registerIdentity(wallet, IIdentity(identity), 840); // 840 = US country code
    }

    function test_provisionedWalletsAreVerified() public {
        assertTrue(ir.isVerified(alice), "alice should be verified");
        assertTrue(ir.isVerified(bob), "bob should be verified");
        assertFalse(ir.isVerified(carol), "carol never passed KYC");
    }

    function test_transferBetweenWhitelisted_succeeds() public {
        token.mint(alice, 100);

        vm.prank(alice);
        token.transfer(bob, 40);

        assertEq(token.balanceOf(alice), 60);
        assertEq(token.balanceOf(bob), 40);
    }

    function test_transferToNonWhitelisted_reverts() public {
        token.mint(alice, 100);

        vm.prank(alice);
        vm.expectRevert("Transfer not possible");
        token.transfer(carol, 10);
    }

    function test_mintToNonWhitelisted_reverts() public {
        vm.expectRevert("Identity is not verified.");
        token.mint(carol, 1);
    }

    /// @notice Compliance admin revokes a wallet's registration -> it can no longer receive.
    function test_revokeIdentityRegistration_blocksIncomingTransfer() public {
        token.mint(alice, 100);
        assertTrue(ir.isVerified(bob));

        ir.deleteIdentity(bob); // agent action

        assertFalse(ir.isVerified(bob));
        vm.prank(alice);
        vm.expectRevert("Transfer not possible");
        token.transfer(bob, 10);
    }

    /// @notice Issuer revokes the KYC claim itself -> verification fails, transfers blocked.
    function test_revokeClaim_blocksIncomingTransfer() public {
        token.mint(alice, 100);

        bytes32 claimId = keccak256(abi.encode(suite.claimIssuer, KYC_TOPIC));
        address bobIdentity = address(ir.identity(bob));

        vm.prank(issuer); // management key of the mock claim issuer
        IClaimIssuer(suite.claimIssuer).revokeClaim(claimId, bobIdentity);

        assertFalse(ir.isVerified(bob), "revoked claim should fail verification");
        vm.prank(alice);
        vm.expectRevert("Transfer not possible");
        token.transfer(bob, 10);
    }

    /// @notice Mirrors the exact on-chain steps the mock KYC backend performs
    ///         (apps/web/lib/kyc/issuer.ts): create an identity managed by the ops key,
    ///         attach an issuer-signed claim from that key, then register the wallet.
    function test_backendProvisioningPath_verifiesAndTransacts() public {
        address wallet = vm.addr(0xDADA);

        bytes32[] memory managementKeys = new bytes32[](1);
        managementKeys[0] = keccak256(abi.encode(address(this))); // ops key manages the identity
        address identity = IIdFactory(suite.idFactory)
            .createIdentityWithManagementKeys(wallet, "backend", managementKeys);

        bytes memory data = abi.encode("backend", "KYC:ok");
        bytes32 dataHash = keccak256(abi.encode(identity, KYC_TOPIC, data));
        bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);

        // No prank: the ops key (address(this)) is the identity's management key.
        IIdentity(identity)
            .addClaim(KYC_TOPIC, 1, suite.claimIssuer, abi.encodePacked(r, s, v), data, "");
        ir.registerIdentity(wallet, IIdentity(identity), 840);

        assertTrue(ir.isVerified(wallet), "backend-provisioned wallet should verify");

        token.mint(wallet, 25);
        vm.prank(wallet);
        token.transfer(alice, 25);
        assertEq(token.balanceOf(alice), 25);
    }

    /// @notice Freezing a wallet immediately blocks it from sending (regulator hold).
    function test_freezeWallet_blocksOutgoingTransfer() public {
        token.mint(alice, 100);

        token.setAddressFrozen(alice, true); // agent action

        vm.prank(alice);
        vm.expectRevert("wallet is frozen");
        token.transfer(bob, 10);
    }
}

