1	// SPDX-License-Identifier: MIT
2	pragma solidity 0.8.17;
3	
4	import { Script, console2 } from "forge-std/Script.sol";
5	import { TREXSuiteDeployer } from "./TREXSuiteDeployer.sol";
6	import { IToken } from "@tokenysolutions/t-rex/contracts/token/IToken.sol";
7	
8	/// @notice Deploys the RoughNet ERC-3643 identity/whitelist suite (issue #2): the full T-REX
9	///         stack plus the mock KYC claim issuer (ADR-0002, ADR-0005). Chain selection uses the
10	///         named `--rpc-url` endpoints in foundry.toml (local | sepolia | polygon | base).
11	///
12	/// Usage:
13	///   forge script script/DeployIdentitySuite.s.sol --rpc-url local --broadcast
14	///   forge script script/DeployIdentitySuite.s.sol --rpc-url sepolia --broadcast --verify
15	///
16	/// Env:
17	///   PRIVATE_KEY      deployer key (hex, 0x-prefixed). Also the default owner/agent/issuer key.
18	///   AGENT_ADDRESS    optional. Identity Registry + token agent (the KYC backend key). Defaults
19	///                    to the deployer.
20	///   KYC_ISSUER_KEY   optional. Address the mock issuer accepts as the KYC claim signer (the key
21	///                    the mock KYC endpoint signs with). Defaults to the deployer.
22	///
23	/// The deployed addresses are printed for wiring into `apps/web` (see .env.example there).
