// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import { Script, console2 } from "forge-std/Script.sol";
import { TREXSuiteDeployer } from "./TREXSuiteDeployer.sol";
import { IToken } from "@tokenysolutions/t-rex/contracts/token/IToken.sol";

/// @notice Deploys the RoughNet ERC-3643 identity/whitelist suite (issue #2): the full T-REX
///         stack plus the mock KYC claim issuer (ADR-0002, ADR-0005). Chain selection uses the
///         named `--rpc-url` endpoints in foundry.toml (local | sepolia | polygon | base).
///
/// Usage:
///   forge script script/DeployIdentitySuite.s.sol --rpc-url local --broadcast
///   forge script script/DeployIdentitySuite.s.sol --rpc-url sepolia --broadcast --verify
///
/// Env:
///   PRIVATE_KEY      deployer key (hex, 0x-prefixed). Also the default owner/agent/issuer key.
///   AGENT_ADDRESS    optional. Identity Registry + token agent (the KYC backend key). Defaults
///                    to the deployer.
///   KYC_ISSUER_KEY   optional. Address the mock issuer accepts as the KYC claim signer (the key
///                    the mock KYC endpoint signs with). Defaults to the deployer.
///
/// The deployed addresses are printed for wiring into `apps/web` (see .env.example there).
contract DeployIdentitySuite is Script, TREXSuiteDeployer {
    function run() external returns (Suite memory suite) {
        uint256 deployerKey = vm.envUint("PRIVATE_KEY");
        address deployer = vm.addr(deployerKey);
        address agent = vm.envOr("AGENT_ADDRESS", deployer);
        address issuerKey = vm.envOr("KYC_ISSUER_KEY", deployer);

        vm.startBroadcast(deployerKey);
        suite = _deployFullSuite(deployer, agent, issuerKey);
        // Tokens deploy paused; unpause so whitelisted transfers work in the demo.
        IToken(suite.token).unpause();
        vm.stopBroadcast();

        console2.log("chainid:                 ", block.chainid);
        console2.log("KYC claim topic:         ", KYC_TOPIC);
        console2.log("Token (RNF):             ", suite.token);
        console2.log("IdentityRegistry:        ", suite.identityRegistry);
        console2.log("IdentityRegistryStorage: ", suite.identityRegistryStorage);
        console2.log("TrustedIssuersRegistry:  ", suite.trustedIssuersRegistry);
        console2.log("ClaimTopicsRegistry:     ", suite.claimTopicsRegistry);
        console2.log("ModularCompliance:       ", suite.modularCompliance);
        console2.log("MockKYCClaimIssuer:      ", suite.claimIssuer);
        console2.log("IdFactory:               ", suite.idFactory);
        console2.log("TREXFactory:             ", suite.trexFactory);
        console2.log("Agent (IR + token):      ", agent);
        console2.log("KYC issuer signer key:   ", issuerKey);
    }
}

