import "server-only";
import {
  type Address,
  type Hex,
  createPublicClient,
  createWalletClient,
  encodeAbiParameters,
  http,
  keccak256,
  stringToHex,
  zeroAddress,
} from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { base, polygon, sepolia } from "viem/chains";
import { defaultChain, defaultChainId } from "@/lib/chains";
import { KYC_TOPIC, getKycContracts, idFactoryAbi, identityAbi, identityRegistryAbi } from "./config";

/**
 * Mock KYC claim issuer — the R1 stand-in for Ctrl Alt's production KYC + ONCHAINID claim
 * service (BRD FR1.8/FR1.9). The boundary is this module: `provisionKyc` always approves
 * (the mock KYC decision) and then performs the *real* on-chain ERC-3643 steps — create a
 * Subscriber ONCHAINID, attach a claim signed by the RoughNet-controlled mock issuer key, and
 * register the wallet in the Identity Registry. The on-chain verification path is therefore
 * identical to production; only this off-chain approval is mocked.
 *
 * Replacing it with Ctrl Alt is an integration swap (issue #11): Ctrl Alt runs the KYC and
 * pushes the signed claim; this module's job collapses to "ask Ctrl Alt, await their claim".
 *
 * The single ops key below must be: owner of the IdFactory, an Identity Registry agent, and a
 * claim-signer key of the mock claim issuer. The deploy script wires all three to the deployer
 * by default, so one key suffices in R1.
 */

const RPC_URL: Record<number, string | undefined> = {
  [sepolia.id]: process.env.NEXT_PUBLIC_SEPOLIA_RPC_URL,
  [polygon.id]: process.env.NEXT_PUBLIC_POLYGON_RPC_URL,
  [base.id]: process.env.NEXT_PUBLIC_BASE_RPC_URL,
  31337: "http://127.0.0.1:8545",
};

export interface KycResult {
  ok: true;
  wallet: Address;
  identity: Address;
  verified: boolean;
  alreadyVerified: boolean;
  createdIdentity: boolean;
  txHashes: Hex[];
}

/** Thrown for configuration problems (missing key/addresses) so the route can return 501. */
export class KycNotConfiguredError extends Error {}

function requireAgentKey(): Hex {
  const key = process.env.KYC_AGENT_PRIVATE_KEY;
  if (!key) {
    throw new KycNotConfiguredError(
      "KYC_AGENT_PRIVATE_KEY is not set; cannot issue mock KYC claims.",
    );
  }
  return (key.startsWith("0x") ? key : `0x${key}`) as Hex;
}

/** keccak256(abi.encode(addr)) — the ONCHAINID key hash used by ERC-734. */
function keyHash(addr: Address): Hex {
  return keccak256(encodeAbiParameters([{ type: "address" }], [addr]));
}

/**
 * Approve KYC for `wallet` and make it verifiable on-chain. Idempotent: re-running for an
 * already-verified wallet is a no-op that reports the existing identity.
 */
export async function provisionKyc(wallet: Address, walletChainId?: number): Promise<KycResult> {
  // The backend can only provision on its configured chain. Reject a wallet connected to a
  // different chain so the user gets a clear error instead of KYC written to a chain the UI
  // (which reads the connected chain) never inspects.
  if (walletChainId !== undefined && walletChainId !== defaultChainId) {
    throw new KycNotConfiguredError(
      `Connected to chain ${walletChainId}, but KYC is served on chain ${defaultChainId}. Switch networks and retry.`,
    );
  }

  const contracts = getKycContracts(defaultChainId);
  if (!contracts) {
    throw new KycNotConfiguredError(
      `KYC suite addresses are not configured for chain ${defaultChainId}.`,
    );
  }

  const account = privateKeyToAccount(requireAgentKey());
  if (account.address.toLowerCase() === wallet.toLowerCase()) {
    throw new KycNotConfiguredError(
      "Connected wallet is the KYC ops key; connect a different wallet for the demo.",
    );
  }

  const transport = http(RPC_URL[defaultChainId]);
  const publicClient = createPublicClient({ chain: defaultChain, transport });
  const walletClient = createWalletClient({ account, chain: defaultChain, transport });

  const txHashes: Hex[] = [];
  const send = async (hash: Hex) => {
    txHashes.push(hash);
    // viem does not throw on a reverted tx — it resolves with status "reverted". Catch it here
    // so a misconfigured ops key (e.g. not the IdFactory owner / IR agent) fails loudly instead
    // of silently proceeding to operate on a zero-address identity.
    const receipt = await publicClient.waitForTransactionReceipt({ hash });
    if (receipt.status !== "success") {
      throw new Error(`KYC transaction reverted: ${hash}`);
    }
  };

  // Already verified? Nothing to do.
  const alreadyVerified = await publicClient.readContract({
    address: contracts.identityRegistry,
    abi: identityRegistryAbi,
    functionName: "isVerified",
    args: [wallet],
  });
  if (alreadyVerified) {
    const identity = await publicClient.readContract({
      address: contracts.identityRegistry,
      abi: identityRegistryAbi,
      functionName: "identity",
      args: [wallet],
    });
    return {
      ok: true,
      wallet,
      identity,
      verified: true,
      alreadyVerified: true,
      createdIdentity: false,
      txHashes,
    };
  }

  // 1. Ensure the wallet has an ONCHAINID (managed by the ops key so it can attach the claim).
  let identity = await publicClient.readContract({
    address: contracts.idFactory,
    abi: idFactoryAbi,
    functionName: "getIdentity",
    args: [wallet],
  });
  let createdIdentity = false;
  if (identity === zeroAddress) {
    const hash = await walletClient.writeContract({
      address: contracts.idFactory,
      abi: idFactoryAbi,
      functionName: "createIdentityWithManagementKeys",
      args: [wallet, wallet.toLowerCase(), [keyHash(account.address)]],
    });
    await send(hash);
    identity = await publicClient.readContract({
      address: contracts.idFactory,
      abi: idFactoryAbi,
      functionName: "getIdentity",
      args: [wallet],
    });
    createdIdentity = true;
  }

  // 2. Sign the KYC claim with the mock issuer key and attach it to the identity.
  //    Matches ClaimIssuer.isClaimValid: sign the Ethereum-prefixed keccak of
  //    abi.encode(identity, topic, data).
  const data = stringToHex("KYC verified by RoughNet mock issuer (R1)");
  const dataHash = keccak256(
    encodeAbiParameters(
      [{ type: "address" }, { type: "uint256" }, { type: "bytes" }],
      [identity, KYC_TOPIC, data],
    ),
  );
  const signature = await walletClient.signMessage({ account, message: { raw: dataHash } });

  const addClaimHash = await walletClient.writeContract({
    address: identity,
    abi: identityAbi,
    functionName: "addClaim",
    args: [KYC_TOPIC, 1n, contracts.claimIssuer, signature, data, ""],
  });
  await send(addClaimHash);

  // 3. Register the wallet -> identity link in the Identity Registry (idempotent guard).
  const registered = await publicClient.readContract({
    address: contracts.identityRegistry,
    abi: identityRegistryAbi,
    functionName: "identity",
    args: [wallet],
  });
  if (registered === zeroAddress) {
    const registerHash = await walletClient.writeContract({
      address: contracts.identityRegistry,
      abi: identityRegistryAbi,
      functionName: "registerIdentity",
      args: [wallet, identity, 840], // 840 = US; country is informational without a country module
    });
    await send(registerHash);
  }

  const verified = await publicClient.readContract({
    address: contracts.identityRegistry,
    abi: identityRegistryAbi,
    functionName: "isVerified",
    args: [wallet],
  });

  return { ok: true, wallet, identity, verified, alreadyVerified: false, createdIdentity, txHashes };
}

import { type Abi, type Address, keccak256, toBytes } from "viem";

/**
 * ERC-3643 KYC / identity wiring for the frontend (issue #2).
 *
 * The on-chain compliance base is the vendored T-REX suite (ADR-0002), deployed by
 * `packages/contracts/script/DeployIdentitySuite.s.sol`. Addresses are populated from env
 * after deploy. Only the off-chain KYC decision is mocked — see `lib/kyc/issuer.ts` and the
 * Ctrl Alt integration tracked by issue #11.
 */

/** Matches `uint256(keccak256("KYC"))` in TREXSuiteDeployer.sol (asserted in config.test.ts). */
export const KYC_TOPIC: bigint = BigInt(keccak256(toBytes("KYC")));

/** Minimal Identity Registry ABI: read verification status, manage Subscriber registration. */
export const identityRegistryAbi = [
  {
    type: "function",
    name: "isVerified",
    inputs: [{ name: "_userAddress", type: "address" }],
    outputs: [{ type: "bool" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "identity",
    inputs: [{ name: "_userAddress", type: "address" }],
    outputs: [{ type: "address" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "registerIdentity",
    inputs: [
      { name: "_userAddress", type: "address" },
      { name: "_identity", type: "address" },
      { name: "_country", type: "uint16" },
    ],
    outputs: [],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "deleteIdentity",
    inputs: [{ name: "_userAddress", type: "address" }],
    outputs: [],
    stateMutability: "nonpayable",
  },
] as const satisfies Abi;

/** Minimal ONCHAINID IdFactory ABI: look up / create a Subscriber identity. */
export const idFactoryAbi = [
  {
    type: "function",
    name: "getIdentity",
    inputs: [{ name: "_wallet", type: "address" }],
    outputs: [{ type: "address" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "createIdentityWithManagementKeys",
    inputs: [
      { name: "_wallet", type: "address" },
      { name: "_salt", type: "string" },
      { name: "_managementKeys", type: "bytes32[]" },
    ],
    outputs: [{ type: "address" }],
    stateMutability: "nonpayable",
  },
] as const satisfies Abi;

/** Minimal ONCHAINID Identity ABI: attach a signed claim (ERC-735). */
export const identityAbi = [
  {
    type: "function",
    name: "addClaim",
    inputs: [
      { name: "_topic", type: "uint256" },
      { name: "_scheme", type: "uint256" },
      { name: "_issuer", type: "address" },
      { name: "_signature", type: "bytes" },
      { name: "_data", type: "bytes" },
      { name: "_uri", type: "string" },
    ],
    outputs: [{ type: "bytes32" }],
    stateMutability: "nonpayable",
  },
] as const satisfies Abi;

export interface KycContracts {
  identityRegistry: Address;
  idFactory: Address;
  claimIssuer: Address;
}

/** Per-chain deployed suite addresses, populated from env (see apps/web/.env.example). */
const ENV: Record<number, Partial<Record<keyof KycContracts, string | undefined>>> = {
  11155111: {
    identityRegistry: process.env.NEXT_PUBLIC_IDENTITY_REGISTRY_SEPOLIA,
    idFactory: process.env.NEXT_PUBLIC_ID_FACTORY_SEPOLIA,
    claimIssuer: process.env.NEXT_PUBLIC_CLAIM_ISSUER_SEPOLIA,
  },
  137: {
    identityRegistry: process.env.NEXT_PUBLIC_IDENTITY_REGISTRY_POLYGON,
    idFactory: process.env.NEXT_PUBLIC_ID_FACTORY_POLYGON,
    claimIssuer: process.env.NEXT_PUBLIC_CLAIM_ISSUER_POLYGON,
  },
  8453: {
    identityRegistry: process.env.NEXT_PUBLIC_IDENTITY_REGISTRY_BASE,
    idFactory: process.env.NEXT_PUBLIC_ID_FACTORY_BASE,
    claimIssuer: process.env.NEXT_PUBLIC_CLAIM_ISSUER_BASE,
  },
  31337: {
    identityRegistry: process.env.NEXT_PUBLIC_IDENTITY_REGISTRY_LOCAL,
    idFactory: process.env.NEXT_PUBLIC_ID_FACTORY_LOCAL,
    claimIssuer: process.env.NEXT_PUBLIC_CLAIM_ISSUER_LOCAL,
  },
};

/** All three addresses for a chain, or undefined if the suite is not configured there. */
export function getKycContracts(chainId: number): KycContracts | undefined {
  const entry = ENV[chainId];
  if (!entry?.identityRegistry || !entry.idFactory || !entry.claimIssuer) return undefined;
  return {
    identityRegistry: entry.identityRegistry as Address,
    idFactory: entry.idFactory as Address,
    claimIssuer: entry.claimIssuer as Address,
  };
}

/** The Identity Registry alone is enough for the client-side read of KYC status. */
export function getIdentityRegistry(chainId: number): Address | undefined {
  const value = ENV[chainId]?.identityRegistry;
  return value && value.length > 0 ? (value as Address) : undefined;
}

