import { base, polygon, sepolia, type Chain } from "viem/chains";

/** Local anvil/hardhat devnet. */
export const localDevnet = {
  id: 31337,
  name: "Local Devnet",
  nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
  rpcUrls: { default: { http: ["http://127.0.0.1:8545"] } },
} as const satisfies Chain;

/** Chains the app understands. Sepolia is the dev/test default (ADR-0006). */
export const supportedChains = [sepolia, polygon, base, localDevnet] as const;

export const defaultChainId = Number(process.env.NEXT_PUBLIC_CHAIN_ID ?? sepolia.id);

export function getChain(chainId: number): Chain | undefined {
  return supportedChains.find((c) => c.id === chainId);
}

export const defaultChain: Chain =
  getChain(defaultChainId) ?? sepolia;

