import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @title MockStablecoin
/// @notice R1 mock standing in for Ctrl Alt's regulated stablecoin / tokenized deposit and its
///         fiat on/off-ramp (BRD FR4.7).
///
///         In production the cash leg of every DvP settlement is a Ctrl Alt-issued regulated
///         stablecoin, minted/redeemed against fiat through their on/off-ramp. RoughNet does not
///         issue that token. For R1 this is a plain ERC-20 with an open {mint} faucet that
///         simulates the on-ramp ("I wired AED, here is the stablecoin"), so the whole primary
///         subscription DvP flow is demoable without any Ctrl Alt infrastructure (ADR-0005).
///
///         The DvP contract ({PrimaryOffering}) depends only on the ERC-20 interface, never on
///         this mock, so replacement is an integration swap: point the offering at Ctrl Alt's
///         token address and stop deploying this contract.
///
/// @dev Decimals default to 6, mirroring USDC/most regulated stablecoins, so price math in
///      {PrimaryOffering} is denominated the same way it will be in production. Ctrl Alt
///      integration tracked by issue #12 (`ctrl-alt-integration`). See ADR-0004, ADR-0005, and
///      CLAUDE.md "Mocks & how to replace them".
contract MockStablecoin is ERC20 {
    uint8 private constant DECIMALS = 6;

    constructor() ERC20("RoughNet Mock USD", "mUSD") { }

    /// @inheritdoc ERC20
    function decimals() public pure override returns (uint8) {
        return DECIMALS;
    }

    /// @notice Open faucet simulating the fiat on-ramp. Anyone can mint test stablecoin to any
    ///         address. This is mock-only behaviour; the real token mints under Ctrl Alt control.
    /// @param to     Recipient of the freshly minted mock stablecoin.
    /// @param amount Amount in the token's smallest unit (6 decimals).
    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

