// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { IToken } from "@tokenysolutions/t-rex/contracts/token/IToken.sol";

/// @title PrimaryOffering
/// @notice Atomic delivery-versus-payment (DvP) primary subscription for RoughNet cells
///         (BRD Epic 4; ADR-0004). A Subscriber buys Fraction Tokens by paying a regulated
///         stablecoin: in a single transaction the stablecoin moves to the Vendor (and an
///         optional platform fee to the fee recipient) and the Fraction Tokens are delivered to
///         the Subscriber by minting the primary issuance. If any leg fails — most importantly if
///         the Subscriber is not whitelisted in the ERC-3643 Identity Registry, or has
///         insufficient stablecoin — the whole transaction reverts. Tokens and cash swap together
///         or not at all (FR4.1).
///
///         Primary-offering parameters are configured per cell by the platform operator
///         (Facilitator role in R1): unit price, discount, optional platform fee, total cap, and
///         a per-investor limit (FR4.4). Settlement events are emitted for the Issuer's banking
///         reconciliation and the off-chain portfolio read-model (FR4.3).
///
///         For R1 the stablecoin is a {MockStablecoin} and there is no Ctrl Alt rail; production
///         swaps in the Ctrl Alt-issued stablecoin behind the same {IERC20} interface (issue #12,
///         ADR-0005). Escrowed / conditional settlement and the fiat-wire fallback leg
///         (FR4.2/FR4.8) are governance-window concerns deferred to Epic 7; primary subscription
///         settles immediately and atomically to the Vendor.
///
/// @dev This contract must hold the ERC-3643 token agent role for each offering's token so it can
///      {IToken.mint}. The token owner grants it via `token.addAgent(address(this))` after the
///      offering is created (see DeployOffering.s.sol). Delivery is a primary mint rather than a
///      transfer of held inventory, which is the accurate model for a *primary* offering and
///      avoids the offering needing its own whitelisted ONCHAINID.
contract PrimaryOffering is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Basis-points denominator (100% = 10_000).
    uint16 public constant BPS = 10_000;

    /// @notice The regulated stablecoin used as the cash leg for every offering (ADR-0004).
    ///         Immutable platform-wide; mocked in R1 (issue #12).
    IERC20 public immutable paymentToken;

    /// @notice Per-cell primary-offering configuration and live state.
    struct Offering {
        IToken token; // ERC-3643 Fraction Token for the cell (delivery leg)
        address vendor; // receives the subscription proceeds (FR4.3)
        uint256 unitPrice; // stablecoin smallest-units per whole Fraction Token, pre-discount
        uint16 discountBps; // primary-offering discount applied to the price (FR4.4)
        uint16 feeBps; // optional platform fee charged on top of the net price
        address feeRecipient; // receives the platform fee (ignored when feeBps == 0)
        uint256 cap; // max total Fraction Tokens sellable in this offering (FR4.4)
        uint256 perInvestorLimit; // max Fraction Tokens a single wallet may buy (0 = no limit)
        uint256 sold; // running total of Fraction Tokens sold
        bool active; // subscriptions only succeed while active
    }

    /// @notice Offerings by id. Ids are assigned sequentially from 0 by {createOffering}.
    Offering[] private _offerings;

    /// @notice Fraction Tokens bought per offering per investor (enforces perInvestorLimit).
    mapping(uint256 => mapping(address => uint256)) public purchased;

    /// @notice Emitted when the operator configures a new per-cell offering.
    event OfferingCreated(
        uint256 indexed offeringId,
        address indexed token,
        address indexed vendor,
        uint256 unitPrice,
        uint16 discountBps,
        uint16 feeBps,
        uint256 cap,
        uint256 perInvestorLimit
    );

    /// @notice Emitted when an offering is opened or closed for subscriptions.
    event OfferingActiveSet(uint256 indexed offeringId, bool active);

    /// @notice Emitted on a successful atomic DvP subscription (the settlement event, FR4.3).
    /// @param offeringId The cell offering.
    /// @param investor   The Subscriber who paid and received Fraction Tokens.
    /// @param quantity   Fraction Tokens delivered.
    /// @param netToVendor Stablecoin paid to the Vendor (proceeds).
    /// @param fee        Stablecoin platform fee paid to the fee recipient.
    /// @param totalPaid  Total stablecoin paid by the Subscriber (netToVendor + fee).
    event Subscribed(
        uint256 indexed offeringId,
        address indexed investor,
        uint256 quantity,
        uint256 netToVendor,
        uint256 fee,
        uint256 totalPaid
    );

    /// @notice Emitted alongside {Subscribed} for the Vendor proceeds leg, so banking
    ///         reconciliation can watch a single dedicated release event (FR4.3).
    event ProceedsReleased(
        uint256 indexed offeringId, address indexed vendor, address indexed investor, uint256 amount
    );

    error InvalidVendor();
    error InvalidToken();
    error InvalidDiscount();
    error InvalidFee();
    error InvalidFeeRecipient();
    error ZeroPrice();
    error ZeroCap();
    error UnknownOffering();
    error OfferingClosed();
    error ZeroQuantity();
    error CapExceeded();
    error PerInvestorLimitExceeded();

    constructor(IERC20 paymentToken_) {
        if (address(paymentToken_) == address(0)) revert InvalidToken();
        paymentToken = paymentToken_;
    }

    /// @notice Configure a new per-cell primary offering.
    /// @dev Operator-only (Facilitator in R1). After calling this, the token owner must grant
    ///      this contract the token agent role so it can mint the delivery leg.
    /// @return offeringId The id of the newly created offering.
    function createOffering(
        IToken token,
        address vendor,
        uint256 unitPrice,
        uint16 discountBps,
        uint16 feeBps,
        address feeRecipient,
        uint256 cap,
        uint256 perInvestorLimit
    ) external onlyOwner returns (uint256 offeringId) {
        if (address(token) == address(0)) revert InvalidToken();
        if (vendor == address(0)) revert InvalidVendor();
        if (unitPrice == 0) revert ZeroPrice();
        if (discountBps > BPS) revert InvalidDiscount();
        if (feeBps > BPS) revert InvalidFee();
        if (feeBps > 0 && feeRecipient == address(0)) revert InvalidFeeRecipient();
        if (cap == 0) revert ZeroCap();

        offeringId = _offerings.length;
        _offerings.push(
            Offering({
                token: token,
                vendor: vendor,
                unitPrice: unitPrice,
                discountBps: discountBps,
                feeBps: feeBps,
                feeRecipient: feeRecipient,
                cap: cap,
                perInvestorLimit: perInvestorLimit,
                sold: 0,
                active: true
            })
        );

        emit OfferingCreated(
            offeringId, address(token), vendor, unitPrice, discountBps, feeBps, cap, perInvestorLimit
        );
        emit OfferingActiveSet(offeringId, true);
    }

    /// @notice Open or close an offering for subscriptions.
    function setOfferingActive(uint256 offeringId, bool active) external onlyOwner {
        Offering storage o = _requireOffering(offeringId);
        o.active = active;
        emit OfferingActiveSet(offeringId, active);
    }

    /// @notice Quote the stablecoin cost of buying `quantity` Fraction Tokens from an offering.
    /// @return netToVendor Proceeds to the Vendor (price after discount).
    /// @return fee         Platform fee on top.
    /// @return totalCost   What the Subscriber pays (netToVendor + fee).
    function quote(uint256 offeringId, uint256 quantity)
        public
        view
        returns (uint256 netToVendor, uint256 fee, uint256 totalCost)
    {
        Offering storage o = _requireOffering(offeringId);
        return _price(o, quantity);
    }

    /// @notice Atomically buy `quantity` Fraction Tokens: pay stablecoin to the Vendor and
    ///         receive freshly minted Fraction Tokens, or revert (DvP — FR4.1).
    /// @dev The delivery leg ({IToken.mint}) enforces ERC-3643 compliance: it reverts if the
    ///      caller is not whitelisted/verified or is frozen, which rolls back the cash leg too.
    function subscribe(uint256 offeringId, uint256 quantity) external nonReentrant {
        Offering storage o = _requireOffering(offeringId);
        if (!o.active) revert OfferingClosed();
        if (quantity == 0) revert ZeroQuantity();
        if (o.sold + quantity > o.cap) revert CapExceeded();

        uint256 alreadyBought = purchased[offeringId][msg.sender];
        if (o.perInvestorLimit != 0 && alreadyBought + quantity > o.perInvestorLimit) {
            revert PerInvestorLimitExceeded();
        }

        (uint256 netToVendor, uint256 fee, uint256 totalPaid) = _price(o, quantity);

        // Effects first (CEI): record the sale before external calls.
        o.sold += quantity;
        purchased[offeringId][msg.sender] = alreadyBought + quantity;

        // Cash leg: stablecoin from Subscriber -> Vendor (proceeds) and -> fee recipient.
        paymentToken.safeTransferFrom(msg.sender, o.vendor, netToVendor);
        if (fee > 0) {
            paymentToken.safeTransferFrom(msg.sender, o.feeRecipient, fee);
        }

        // Delivery leg: primary mint of Fraction Tokens to the Subscriber. Reverts (and unwinds
        // the cash leg) if the Subscriber is not a verified, unfrozen ERC-3643 holder.
        o.token.mint(msg.sender, quantity);

        emit Subscribed(offeringId, msg.sender, quantity, netToVendor, fee, totalPaid);
        emit ProceedsReleased(offeringId, o.vendor, msg.sender, netToVendor);
    }

    /// @notice Number of offerings created so far (ids are 0..count-1).
    function offeringCount() external view returns (uint256) {
        return _offerings.length;
    }

    /// @notice Read an offering's configuration and live state.
    function getOffering(uint256 offeringId) external view returns (Offering memory) {
        return _requireOffering(offeringId);
    }

    /// @notice Fraction Tokens still available for sale in an offering.
    function remaining(uint256 offeringId) external view returns (uint256) {
        Offering storage o = _requireOffering(offeringId);
        return o.cap - o.sold;
    }

    function _price(Offering storage o, uint256 quantity)
        private
        view
        returns (uint256 netToVendor, uint256 fee, uint256 totalCost)
    {
        uint256 gross = quantity * o.unitPrice;
        uint256 discount = (gross * o.discountBps) / BPS;
        netToVendor = gross - discount;
        fee = (netToVendor * o.feeBps) / BPS;
        totalCost = netToVendor + fee;
    }

    function _requireOffering(uint256 offeringId) private view returns (Offering storage) {
        if (offeringId >= _offerings.length) revert UnknownOffering();
        return _offerings[offeringId];
    }
}

