// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

import { Test } from "forge-std/Test.sol";
import { TREXSuiteDeployer } from "../script/TREXSuiteDeployer.sol";
import { PrimaryOffering } from "../src/PrimaryOffering.sol";
import { MockStablecoin } from "../src/mocks/MockStablecoin.sol";

import { IToken } from "@tokenysolutions/t-rex/contracts/token/IToken.sol";
import {
    IIdentityRegistry
} from "@tokenysolutions/t-rex/contracts/registry/interface/IIdentityRegistry.sol";
import { IIdFactory } from "@onchain-id/solidity/contracts/factory/IIdFactory.sol";
import { IIdentity } from "@onchain-id/solidity/contracts/interface/IIdentity.sol";

/// @notice Minimal view of the AgentRole on the concrete ERC-3643 token (not exposed by IToken).
interface ITokenAgent {
    function addAgent(address agent) external;
}

/// @notice Acceptance tests for issue #3 — primary subscription & atomic DvP settlement (Epic 4).
///         Runs against a real ERC-3643 suite (only the off-chain KYC decision is mocked, as in
///         issue #2) so the compliance-gated delivery leg is exercised for real.
contract PrimaryOfferingTest is Test, TREXSuiteDeployer {
    Suite internal suite;
    IToken internal token;
    IIdentityRegistry internal ir;
    MockStablecoin internal usd;
    PrimaryOffering internal offering;

    uint256 internal constant ISSUER_PK = 0xA11CE;
    address internal issuer;

    address internal vendor = address(0x5EED);
    address internal feeRecipient = address(0xFEE5);

    uint256 internal constant ALICE_PK = 0xA1;
    uint256 internal constant BOB_PK = 0xB0B;
    uint256 internal constant CAROL_PK = 0xCA401;
    address internal alice; // whitelisted subscriber
    address internal bob; // whitelisted subscriber
    address internal carol; // never passes KYC

    // 6-decimal stablecoin; token has 0 decimals (whole fractions).
    uint256 internal constant UNIT = 1e6;
    uint256 internal constant PRICE = 100 * UNIT; // 100 mUSD per fraction

    function setUp() public {
        issuer = vm.addr(ISSUER_PK);
        suite = _deployFullSuite(address(this), address(this), issuer);
        token = IToken(suite.token);
        ir = IIdentityRegistry(suite.identityRegistry);
        token.unpause();

        alice = _provision("alice", ALICE_PK);
        bob = _provision("bob", BOB_PK);
        carol = vm.addr(CAROL_PK);

        usd = new MockStablecoin();
        offering = new PrimaryOffering(usd);

        // Grant the offering the token agent role so it can mint the delivery leg.
        ITokenAgent(suite.token).addAgent(address(offering));

        // Fund subscribers with mock stablecoin (simulated on-ramp) and approve the offering.
        usd.mint(alice, 1_000_000 * UNIT);
        usd.mint(bob, 1_000_000 * UNIT);
        vm.prank(alice);
        usd.approve(address(offering), type(uint256).max);
        vm.prank(bob);
        usd.approve(address(offering), type(uint256).max);
    }

    function _provision(string memory label, uint256 walletPk) internal returns (address wallet) {
        wallet = vm.addr(walletPk);
        address identity = IIdFactory(suite.idFactory).createIdentity(wallet, label);
        bytes memory data = abi.encode(label, "KYC:ok");
        bytes32 dataHash = keccak256(abi.encode(identity, KYC_TOPIC, data));
        bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);
        vm.prank(wallet);
        IIdentity(identity).addClaim(KYC_TOPIC, 1, suite.claimIssuer, abi.encodePacked(r, s, v), data, "");
        ir.registerIdentity(wallet, IIdentity(identity), 840);
    }

    /// Create a vanilla offering (no discount, no fee) with the given caps.
    function _createPlain(uint256 cap, uint256 perInvestorLimit) internal returns (uint256 id) {
        id = offering.createOffering(token, vendor, PRICE, 0, 0, address(0), cap, perInvestorLimit);
    }

    // --- DvP happy path -----------------------------------------------------

    function test_subscribe_atomicDvp_movesTokensAndCash() public {
        uint256 id = _createPlain(1_000, 0);

        uint256 qty = 10;
        uint256 cost = qty * PRICE;

        vm.expectEmit(true, true, false, true, address(offering));
        emit PrimaryOffering.Subscribed(id, alice, qty, cost, 0, cost);

        vm.prank(alice);
        offering.subscribe(id, qty);

        assertEq(token.balanceOf(alice), qty, "fractions delivered");
        assertEq(usd.balanceOf(vendor), cost, "vendor received proceeds");
        assertEq(usd.balanceOf(alice), 1_000_000 * UNIT - cost, "subscriber debited");
        assertEq(offering.purchased(id, alice), qty);
        assertEq(offering.remaining(id), 990);
    }

    function test_subscribe_quoteMatchesCharge() public {
        uint256 id = offering.createOffering(token, vendor, PRICE, 1_000, 250, feeRecipient, 1_000, 0);
        uint256 qty = 4;

        // 1000 bps discount = 10% off; 250 bps fee on the net.
        uint256 gross = qty * PRICE;
        uint256 net = gross - (gross * 1_000) / 10_000;
        uint256 fee = (net * 250) / 10_000;
        uint256 total = net + fee;

        (uint256 qNet, uint256 qFee, uint256 qTotal) = offering.quote(id, qty);
        assertEq(qNet, net);
        assertEq(qFee, fee);
        assertEq(qTotal, total);

        vm.prank(alice);
        offering.subscribe(id, qty);

        assertEq(usd.balanceOf(vendor), net, "vendor gets discounted net");
        assertEq(usd.balanceOf(feeRecipient), fee, "platform gets fee");
        assertEq(usd.balanceOf(alice), 1_000_000 * UNIT - total, "subscriber pays net+fee");
        assertEq(token.balanceOf(alice), qty);
    }

    // --- Atomicity / reverts ------------------------------------------------

    function test_subscribe_nonWhitelisted_revertsAndMovesNothing() public {
        uint256 id = _createPlain(1_000, 0);
        usd.mint(carol, 1_000_000 * UNIT);
        vm.prank(carol);
        usd.approve(address(offering), type(uint256).max);

        uint256 vendorBefore = usd.balanceOf(vendor);
        uint256 carolBefore = usd.balanceOf(carol);

        // Delivery leg (mint to unverified carol) reverts -> whole DvP unwinds, cash untouched.
        vm.prank(carol);
        vm.expectRevert("Identity is not verified.");
        offering.subscribe(id, 5);

        assertEq(usd.balanceOf(vendor), vendorBefore, "vendor not paid on revert");
        assertEq(usd.balanceOf(carol), carolBefore, "subscriber not debited on revert");
        assertEq(token.balanceOf(carol), 0);
        assertEq(offering.purchased(id, carol), 0);
    }

    function test_subscribe_insufficientBalance_revertsAtomically() public {
        uint256 id = _createPlain(1_000, 0);
        address poor = _provision("poor", 0xDEAD);
        vm.prank(poor);
        usd.approve(address(offering), type(uint256).max);
        // poor has zero stablecoin.

        vm.prank(poor);
        vm.expectRevert();
        offering.subscribe(id, 1);

        assertEq(token.balanceOf(poor), 0, "no fractions without payment");
        assertEq(offering.purchased(id, poor), 0);
    }

    // --- Offering parameter enforcement -------------------------------------

    function test_subscribe_capEnforced() public {
        uint256 id = _createPlain(15, 0);

        vm.prank(alice);
        offering.subscribe(id, 10);

        vm.prank(bob);
        vm.expectRevert(PrimaryOffering.CapExceeded.selector);
        offering.subscribe(id, 6);

        // Exactly hitting the cap is allowed.
        vm.prank(bob);
        offering.subscribe(id, 5);
        assertEq(offering.remaining(id), 0);
    }

    function test_subscribe_perInvestorLimitEnforced() public {
        uint256 id = _createPlain(1_000, 20);

        vm.prank(alice);
        offering.subscribe(id, 20);

        vm.prank(alice);
        vm.expectRevert(PrimaryOffering.PerInvestorLimitExceeded.selector);
        offering.subscribe(id, 1);

        // A different investor still has their own limit.
        vm.prank(bob);
        offering.subscribe(id, 20);
        assertEq(token.balanceOf(bob), 20);
    }

    function test_subscribe_inactiveOffering_reverts() public {
        uint256 id = _createPlain(1_000, 0);
        offering.setOfferingActive(id, false);

        vm.prank(alice);
        vm.expectRevert(PrimaryOffering.OfferingClosed.selector);
        offering.subscribe(id, 1);
    }

    function test_subscribe_zeroQuantity_reverts() public {
        uint256 id = _createPlain(1_000, 0);
        vm.prank(alice);
        vm.expectRevert(PrimaryOffering.ZeroQuantity.selector);
        offering.subscribe(id, 0);
    }

    function test_subscribe_unknownOffering_reverts() public {
        vm.prank(alice);
        vm.expectRevert(PrimaryOffering.UnknownOffering.selector);
        offering.subscribe(0, 1);
    }

    // --- Access control & validation ----------------------------------------

    function test_createOffering_onlyOwner() public {
        vm.prank(alice);
        vm.expectRevert("Ownable: caller is not the owner");
        offering.createOffering(token, vendor, PRICE, 0, 0, address(0), 100, 0);
    }

    function test_setOfferingActive_onlyOwner() public {
        uint256 id = _createPlain(100, 0);
        vm.prank(alice);
        vm.expectRevert("Ownable: caller is not the owner");
        offering.setOfferingActive(id, false);
    }

    function test_createOffering_rejectsBadParams() public {
        vm.expectRevert(PrimaryOffering.ZeroPrice.selector);
        offering.createOffering(token, vendor, 0, 0, 0, address(0), 100, 0);

        vm.expectRevert(PrimaryOffering.InvalidVendor.selector);
        offering.createOffering(token, address(0), PRICE, 0, 0, address(0), 100, 0);

        vm.expectRevert(PrimaryOffering.InvalidDiscount.selector);
        offering.createOffering(token, vendor, PRICE, 10_001, 0, address(0), 100, 0);

        vm.expectRevert(PrimaryOffering.InvalidFeeRecipient.selector);
        offering.createOffering(token, vendor, PRICE, 0, 100, address(0), 100, 0);

        vm.expectRevert(PrimaryOffering.ZeroCap.selector);
        offering.createOffering(token, vendor, PRICE, 0, 0, address(0), 0, 0);
    }

    function test_createOffering_assignsSequentialIds() public {
        uint256 a = _createPlain(100, 0);
        uint256 b = _createPlain(100, 0);
        assertEq(a, 0);
        assertEq(b, 1);
        assertEq(offering.offeringCount(), 2);
    }

    function testFuzz_subscribe_neverExceedsCap(uint256 q1, uint256 q2) public {
        uint256 cap = 100;
        uint256 id = _createPlain(cap, 0);
        q1 = bound(q1, 1, cap);
        q2 = bound(q2, 1, cap);

        vm.prank(alice);
        offering.subscribe(id, q1);

        if (q1 + q2 > cap) {
            vm.prank(bob);
            vm.expectRevert(PrimaryOffering.CapExceeded.selector);
            offering.subscribe(id, q2);
        } else {
            vm.prank(bob);
            offering.subscribe(id, q2);
        }

        PrimaryOffering.Offering memory o = offering.getOffering(id);
        assertLe(o.sold, cap);
    }
}

