///         role so it can mint, and creates one demo offering for an existing Fraction Token.
///         Run AFTER DeployIdentitySuite (it needs the deployed ERC-3643 token + its owner key).
///
/// Usage:
///   forge script script/DeployOffering.s.sol --rpc-url local --broadcast
///   forge script script/DeployOffering.s.sol --rpc-url sepolia --broadcast --verify
///
/// Env:
///   PRIVATE_KEY        deployer key (hex). Must be the token OWNER so it can grant the agent role.
///   TOKEN_ADDRESS      the deployed ERC-3643 Fraction Token (RNF) from DeployIdentitySuite.
///   VENDOR_ADDRESS     optional. Receives subscription proceeds. Defaults to the deployer.
///   OFFERING_PRICE     optional. Stablecoin (6dp) units per fraction. Default 100_000000 (100).
///   OFFERING_DISCOUNT_BPS  optional. Primary-offering discount in bps. Default 0.
///   OFFERING_FEE_BPS       optional. Platform fee in bps. Default 0.
///   OFFERING_CAP          optional. Total fractions sellable. Default 1_000_000.
///   OFFERING_PER_INVESTOR optional. Per-wallet fraction limit (0 = none). Default 0.
contract DeployOffering is Script {
    function run()
        external
        returns (MockStablecoin stablecoin, PrimaryOffering offering, uint256 offeringId)
    {
        uint256 deployerKey = vm.envUint("PRIVATE_KEY");
        address deployer = vm.addr(deployerKey);
        address tokenAddr = vm.envAddress("TOKEN_ADDRESS");
        address vendor = vm.envOr("VENDOR_ADDRESS", deployer);
        uint256 price = vm.envOr("OFFERING_PRICE", uint256(100_000000));
        uint256 discountBps = vm.envOr("OFFERING_DISCOUNT_BPS", uint256(0));
        uint256 feeBps = vm.envOr("OFFERING_FEE_BPS", uint256(0));
        uint256 cap = vm.envOr("OFFERING_CAP", uint256(1_000_000));
        uint256 perInvestor = vm.envOr("OFFERING_PER_INVESTOR", uint256(0));

        vm.startBroadcast(deployerKey);

        stablecoin = new MockStablecoin();
        offering = new PrimaryOffering(stablecoin);

        // The offering mints the delivery leg, so it must be a token agent. Requires the
        // deployer to be the token owner (the DeployIdentitySuite default).
        ITokenAgent(tokenAddr).addAgent(address(offering));

        offeringId = offering.createOffering(
            IToken(tokenAddr),
            vendor,
            price,
            uint16(discountBps),
            uint16(feeBps),
            feeBps > 0 ? deployer : address(0),
            cap,
            perInvestor
        );

        vm.stopBroadcast();

        console2.log("chainid:           ", block.chainid);
        console2.log("MockStablecoin:    ", address(stablecoin));
        console2.log("PrimaryOffering:   ", address(offering));
        console2.log("Fraction Token:    ", tokenAddr);
        console2.log("Vendor:            ", vendor);
        console2.log("Demo offering id:  ", offeringId);
        console2.log("Unit price (6dp):  ", price);
        console2.log("Discount bps:      ", discountBps);
        console2.log("Fee bps:           ", feeBps);
        console2.log("Cap:               ", cap);
        console2.log("Per-investor limit:", perInvestor);
    }
}

