import { NextResponse } from "next/server";
import { isAddress } from "viem";
import { getSettlementsRepository, type NewSettlementRecord } from "@/lib/db";
import { aggregateHoldings } from "@/lib/portfolio/holdings";

export const dynamic = "force-dynamic";

/**
 * Primary-subscription settlement read-model (issue #3, FR4.6). GET returns a wallet's
 * settlement history and derived holdings (cost basis); POST records a confirmed DvP
 * subscription so the portfolio reflects it. The on-chain {Subscribed} event is the source of
 * truth; this is the off-chain projection used by the UI (and the Ctrl Alt reconciliation seam,
 * FR4.9 / issue #12).
 */
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const investor = searchParams.get("investor") ?? undefined;
  if (investor !== undefined && !isAddress(investor)) {
    return NextResponse.json({ error: "Invalid `investor` address" }, { status: 400 });
  }

  const repo = getSettlementsRepository();
  const settlements = await repo.list(investor);
  const holdings = aggregateHoldings(settlements);
  return NextResponse.json({ settlements, holdings });
}

const DECIMAL = /^\d+$/;

function parseBody(body: unknown): NewSettlementRecord | null {
  if (typeof body !== "object" || body === null) return null;
  const b = body as Record<string, unknown>;
  const amounts = ["quantity", "netToVendor", "fee", "totalPaid"] as const;
  if (
    typeof b.chainId !== "number" ||
    typeof b.offeringId !== "number" ||
    typeof b.token !== "string" ||
    !isAddress(b.token) ||
    typeof b.investor !== "string" ||
    !isAddress(b.investor) ||
    typeof b.vendor !== "string" ||
    !isAddress(b.vendor) ||
    typeof b.txHash !== "string" ||
    b.txHash.length === 0 ||
    amounts.some((k) => typeof b[k] !== "string" || !DECIMAL.test(b[k] as string))
  ) {
    return null;
  }
  return {
    chainId: b.chainId,
    offeringId: b.offeringId,
    token: b.token,
    investor: b.investor,
    vendor: b.vendor,
    quantity: b.quantity as string,
    netToVendor: b.netToVendor as string,
    fee: b.fee as string,
    totalPaid: b.totalPaid as string,
    txHash: b.txHash,
  };
}

export async function POST(request: Request) {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const record = parseBody(json);
  if (!record) {
    return NextResponse.json({ error: "Invalid settlement payload" }, { status: 400 });
  }

  const repo = getSettlementsRepository();
  const saved = await repo.add(record);
  return NextResponse.json({ settlement: saved }, { status: 201 });
}

