import type { Abi, Address } from "viem";

/**
 * Primary-subscription DvP wiring for the frontend (issue #3, Epic 4).
 *
 * On-chain: {PrimaryOffering} (atomic DvP) + {MockStablecoin} (the cash leg, mocked in R1 —
 * Ctrl Alt seam #12) + the ERC-3643 Fraction Token from issue #2. Addresses are populated from
 * env after `pnpm --filter @roughnet/contracts deploy:offering:<chain>`.
 */

/** Hand-maintained ABI subset of PrimaryOffering.sol used by the UI. */
export const primaryOfferingAbi = [
  {
    type: "function",
    name: "paymentToken",
    inputs: [],
    outputs: [{ type: "address" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "quote",
    inputs: [
      { name: "offeringId", type: "uint256" },
      { name: "quantity", type: "uint256" },
    ],
    outputs: [
      { name: "netToVendor", type: "uint256" },
      { name: "fee", type: "uint256" },
      { name: "totalCost", type: "uint256" },
    ],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "subscribe",
    inputs: [
      { name: "offeringId", type: "uint256" },
      { name: "quantity", type: "uint256" },
    ],
    outputs: [],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "remaining",
    inputs: [{ name: "offeringId", type: "uint256" }],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "purchased",
    inputs: [
      { name: "offeringId", type: "uint256" },
      { name: "investor", type: "address" },
    ],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "getOffering",
    inputs: [{ name: "offeringId", type: "uint256" }],
    outputs: [
      {
        type: "tuple",
        components: [
          { name: "token", type: "address" },
          { name: "vendor", type: "address" },
          { name: "unitPrice", type: "uint256" },
          { name: "discountBps", type: "uint16" },
          { name: "feeBps", type: "uint16" },
          { name: "feeRecipient", type: "address" },
          { name: "cap", type: "uint256" },
          { name: "perInvestorLimit", type: "uint256" },
          { name: "sold", type: "uint256" },
          { name: "active", type: "bool" },
        ],
      },
    ],
    stateMutability: "view",
  },
] as const satisfies Abi;

/** Minimal ERC-20 ABI for the stablecoin: balance, allowance, approve, and the mock faucet. */
export const erc20Abi = [
  {
    type: "function",
    name: "balanceOf",
    inputs: [{ name: "account", type: "address" }],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "decimals",
    inputs: [],
    outputs: [{ type: "uint8" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "allowance",
    inputs: [
      { name: "owner", type: "address" },
      { name: "spender", type: "address" },
    ],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "approve",
    inputs: [
      { name: "spender", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [{ type: "bool" }],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "mint",
    inputs: [
      { name: "to", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [],
    stateMutability: "nonpayable",
  },
] as const satisfies Abi;

/** Minimal Fraction Token (ERC-3643) ABI for reading the connected wallet's balance. */
export const fractionTokenAbi = [
  {
    type: "function",
    name: "balanceOf",
    inputs: [{ name: "account", type: "address" }],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
] as const satisfies Abi;

export interface OfferingContracts {
  offering: Address;
  stablecoin: Address;
  token: Address;
}

const ENV: Record<number, Partial<Record<keyof OfferingContracts, string | undefined>>> = {
  11155111: {
    offering: process.env.NEXT_PUBLIC_OFFERING_SEPOLIA,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_SEPOLIA,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_SEPOLIA,
  },
  137: {
    offering: process.env.NEXT_PUBLIC_OFFERING_POLYGON,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_POLYGON,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_POLYGON,
  },
  8453: {
    offering: process.env.NEXT_PUBLIC_OFFERING_BASE,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_BASE,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_BASE,
  },
  31337: {
    offering: process.env.NEXT_PUBLIC_OFFERING_LOCAL,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_LOCAL,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_LOCAL,
  },
};

/** All three addresses for a chain, or undefined if the offering is not configured there. */
export function getOfferingContracts(chainId: number): OfferingContracts | undefined {
  const e = ENV[chainId];
  if (!e?.offering || !e.stablecoin || !e.token) return undefined;
  return {
    offering: e.offering as Address,
    stablecoin: e.stablecoin as Address,
    token: e.token as Address,
  };
}

/** The demo offering id the UI subscribes to (default 0; configurable for multi-cell demos). */
export const defaultOfferingId = BigInt(process.env.NEXT_PUBLIC_OFFERING_ID ?? "0");

