  },
  {
    type: "function",
    name: "allowance",
    inputs: [
      { name: "owner", type: "address" },
      { name: "spender", type: "address" },
    ],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "approve",
    inputs: [
      { name: "spender", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [{ type: "bool" }],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "mint",
    inputs: [
      { name: "to", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [],
    stateMutability: "nonpayable",
  },
] as const satisfies Abi;

/** Minimal Fraction Token (ERC-3643) ABI for reading the connected wallet's balance. */
export const fractionTokenAbi = [
  {
    type: "function",
    name: "balanceOf",
    inputs: [{ name: "account", type: "address" }],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
] as const satisfies Abi;

export interface OfferingContracts {
  offering: Address;
  stablecoin: Address;
  token: Address;
}

const ENV: Record<number, Partial<Record<keyof OfferingContracts, string | undefined>>> = {
  11155111: {
    offering: process.env.NEXT_PUBLIC_OFFERING_SEPOLIA,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_SEPOLIA,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_SEPOLIA,
  },
  137: {
    offering: process.env.NEXT_PUBLIC_OFFERING_POLYGON,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_POLYGON,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_POLYGON,
  },
  8453: {
    offering: process.env.NEXT_PUBLIC_OFFERING_BASE,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_BASE,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_BASE,
  },
  31337: {
    offering: process.env.NEXT_PUBLIC_OFFERING_LOCAL,
    stablecoin: process.env.NEXT_PUBLIC_STABLECOIN_LOCAL,
    token: process.env.NEXT_PUBLIC_FRACTION_TOKEN_LOCAL,
  },
};

/** All three addresses for a chain, or undefined if the offering is not configured there. */
export function getOfferingContracts(chainId: number): OfferingContracts | undefined {
  const e = ENV[chainId];
  if (!e?.offering || !e.stablecoin || !e.token) return undefined;
  return {
    offering: e.offering as Address,
    stablecoin: e.stablecoin as Address,
    token: e.token as Address,
  };
}

/** The demo offering id the UI subscribes to (default 0; configurable for multi-cell demos). */
export const defaultOfferingId = BigInt(process.env.NEXT_PUBLIC_OFFERING_ID ?? "0");

