"use client";

import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useEffect, useMemo, useState } from "react";
import { formatUnits } from "viem";
import {
  useAccount,
  useReadContract,
  useWaitForTransactionReceipt,
  useWriteContract,
} from "wagmi";
import {
  defaultOfferingId,
  erc20Abi,
  fractionTokenAbi,
  getOfferingContracts,
  primaryOfferingAbi,
} from "@/lib/offering/config";

const BPS = 10_000n;

/** Mirror of PrimaryOffering._price so the UI shows the exact on-chain charge live. */
function priceFor(
  quantity: bigint,
  unitPrice: bigint,
  discountBps: bigint,
  feeBps: bigint,
): { net: bigint; fee: bigint; total: bigint } {
  const gross = quantity * unitPrice;
  const discount = (gross * discountBps) / BPS;
  const net = gross - discount;
  const fee = (net * feeBps) / BPS;
  return { net, fee, total: net + fee };
}

/**
 * Primary-subscription DvP flow (issue #3, FR4.5): shows live price/discount/fees and the
 * connected wallet's stablecoin balance, then settles atomically — stablecoin to the Vendor and
 * freshly minted Fraction Tokens to the Subscriber in one transaction, or revert. The cash leg
 * is a mock stablecoin in R1 (Ctrl Alt seam #12); a faucet button simulates the fiat on-ramp.
 */
export function SubscriptionPanel() {
  const { address, chainId, isConnected } = useAccount();
  const contracts = chainId ? getOfferingContracts(chainId) : undefined;
  const offeringId = defaultOfferingId;

  const [qtyInput, setQtyInput] = useState("1");
  const quantity = useMemo(() => {
    try {
      const q = BigInt(qtyInput || "0");
      return q > 0n ? q : 0n;
    } catch {
      return 0n;
    }
  }, [qtyInput]);

  const enabled = Boolean(contracts);

  const offeringRead = useReadContract({
    abi: primaryOfferingAbi,
    address: contracts?.offering,
    functionName: "getOffering",
    args: [offeringId],
    query: { enabled },
  });
  const decimalsRead = useReadContract({
    abi: erc20Abi,
    address: contracts?.stablecoin,
    functionName: "decimals",
    query: { enabled },
  });
  const balanceRead = useReadContract({
    abi: erc20Abi,
    address: contracts?.stablecoin,
    functionName: "balanceOf",
    args: address ? [address] : undefined,
    query: { enabled: enabled && Boolean(address) },
  });
  const allowanceRead = useReadContract({
    abi: erc20Abi,
    address: contracts?.stablecoin,
    functionName: "allowance",
    args: address && contracts ? [address, contracts.offering] : undefined,
    query: { enabled: enabled && Boolean(address) },
  });

  const offering = offeringRead.data;
  const decimals = decimalsRead.data ?? 6;
  const balance = balanceRead.data ?? 0n;
  const allowance = allowanceRead.data ?? 0n;

  const cost = offering
    ? priceFor(quantity, offering.unitPrice, BigInt(offering.discountBps), BigInt(offering.feeBps))
    : null;
  const fmt = (v: bigint) => formatUnits(v, decimals);

  const needsApproval = Boolean(cost && cost.total > allowance);
  const insufficientBalance = Boolean(cost && cost.total > balance);

  const approve = useWriteContract();
  const approveReceipt = useWaitForTransactionReceipt({ hash: approve.data });
  const subscribe = useWriteContract();
  const subscribeReceipt = useWaitForTransactionReceipt({ hash: subscribe.data });
  const faucet = useWriteContract();
  const faucetReceipt = useWaitForTransactionReceipt({ hash: faucet.data });

  // Refresh allowance once an approval confirms.
  useEffect(() => {
    if (approveReceipt.isSuccess) void allowanceRead.refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [approveReceipt.isSuccess]);

  // Refresh balance once the faucet confirms.
  useEffect(() => {
    if (faucetReceipt.isSuccess) void balanceRead.refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [faucetReceipt.isSuccess]);

  // Once the DvP tx confirms, persist the settlement to the portfolio read-model and refresh.
  useEffect(() => {
    if (!subscribeReceipt.isSuccess || !subscribe.data || !address || !chainId) return;
    if (!offering || !cost) return;
    void (async () => {
      await fetch("/api/portfolio", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          chainId,
          offeringId: Number(offeringId),
          token: offering.token,
          investor: address,
          vendor: offering.vendor,
          quantity: quantity.toString(),
          netToVendor: cost.net.toString(),
          fee: cost.fee.toString(),
          totalPaid: cost.total.toString(),
          txHash: subscribe.data,
        }),
      });
      await Promise.all([balanceRead.refetch(), allowanceRead.refetch(), offeringRead.refetch()]);
      window.dispatchEvent(new CustomEvent("roughnet:settlement"));
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [subscribeReceipt.isSuccess]);

  const onApprove = () => {
    if (!contracts || !cost) return;
    approve.writeContract({
      abi: erc20Abi,
      address: contracts.stablecoin,
      functionName: "approve",
      args: [contracts.offering, cost.total],
    });
  };

  const onSubscribe = () => {
    if (!contracts || quantity === 0n) return;
    subscribe.writeContract({
      abi: primaryOfferingAbi,
      address: contracts.offering,
      functionName: "subscribe",
      args: [offeringId, quantity],
    });
  };

  const onFaucet = () => {
    if (!contracts || !address || !cost) return;
    // Mint enough mock stablecoin to cover the current order (simulated fiat on-ramp).
    const amount = cost.total > 0n ? cost.total : 1000n * 10n ** BigInt(decimals);
    faucet.writeContract({
      abi: erc20Abi,
      address: contracts.stablecoin,
      functionName: "mint",
      args: [address, amount],
    });
  };

  return (
    <section className="panel">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>Subscribe — primary offering (atomic DvP)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to subscribe.</p>
      ) : !contracts ? (
        <p className="muted">No primary offering deployed on the connected chain (chainId {chainId}).</p>
      ) : offeringRead.isLoading ? (
        <p className="muted">Loading offering…</p>
      ) : !offering ? (
        <p className="muted">⚠ Offering #{offeringId.toString()} not found.</p>
      ) : (
        <>
          <p className="muted">
            Unit price: <strong>{fmt(offering.unitPrice)} mUSD</strong>
            {offering.discountBps > 0 ? <> · discount {offering.discountBps / 100}%</> : null}
            {offering.feeBps > 0 ? <> · fee {offering.feeBps / 100}%</> : null}
            {" · "}sold {offering.sold.toString()}/{offering.cap.toString()}
            {!offering.active ? <> · <strong>closed</strong></> : null}
          </p>
          <p className="muted">
            Your stablecoin balance: <strong>{fmt(balance)} mUSD</strong>{" "}
            <button onClick={onFaucet} disabled={faucet.isPending || faucetReceipt.isLoading}>
              {faucet.isPending || faucetReceipt.isLoading ? "Funding…" : "Get mock mUSD"}
            </button>
          </p>

          <div className="row">
            <label>
              Quantity (fractions){" "}
              <input
                type="number"
                min={1}
                step={1}
                value={qtyInput}
                onChange={(e) => setQtyInput(e.target.value)}
              />
            </label>
          </div>

          {cost ? (
            <ul className="records">
              <li>Net to vendor: <strong>{fmt(cost.net)} mUSD</strong></li>
              <li>Platform fee: <strong>{fmt(cost.fee)} mUSD</strong></li>
              <li>You pay (DvP total): <strong>{fmt(cost.total)} mUSD</strong></li>
            </ul>
          ) : null}

          {insufficientBalance ? (
            <p className="muted">⚠ Insufficient stablecoin — use the faucet above.</p>
          ) : null}

          <div className="row">
            {needsApproval ? (
              <button
                onClick={onApprove}
                disabled={
                  quantity === 0n || approve.isPending || approveReceipt.isLoading || insufficientBalance
                }
              >
                {approve.isPending
                  ? "Confirm approval…"
                  : approveReceipt.isLoading
                    ? "Approving…"
                    : "Approve stablecoin"}
              </button>
            ) : (
              <button
                onClick={onSubscribe}
                disabled={
                  quantity === 0n ||
                  !offering.active ||
                  subscribe.isPending ||
                  subscribeReceipt.isLoading ||
                  insufficientBalance
                }
              >
                {subscribe.isPending
                  ? "Confirm in wallet…"
                  : subscribeReceipt.isLoading
                    ? "Settling DvP…"
                    : "Subscribe (swap cash ↔ tokens)"}
              </button>
            )}
          </div>

          {approve.error ? <p className="muted">⚠ {approve.error.message}</p> : null}
          {subscribe.error ? <p className="muted">⚠ {subscribe.error.message}</p> : null}
          {subscribeReceipt.isSuccess ? (
            <p className="muted">✓ DvP settled — tokens delivered, vendor paid, portfolio updated.</p>
          ) : null}
          <p className="muted">
            Not whitelisted yet? Run mock KYC above first — the delivery leg reverts (and your cash
            stays put) until your wallet is verified.
          </p>
        </>
      )}
    </section>
  );
}

