"use client";

import { useCallback, useEffect, useState } from "react";
import { formatUnits } from "viem";
import { useAccount } from "wagmi";
import type { SettlementRecord } from "@/lib/db/settlements";
import type { Holding } from "@/lib/portfolio/holdings";

const STABLECOIN_DECIMALS = 6; // MockStablecoin (mUSD)

/**
 * Subscriber portfolio (issue #3, FR4.6): holdings with cost basis and settlement history for
 * the connected wallet, read from the off-chain settlement read-model (/api/portfolio). Listens
 * for the `roughnet:settlement` event the subscription flow dispatches so it refreshes right
 * after a DvP settles.
 */
export function Portfolio() {
  const { address, isConnected } = useAccount();
  const [holdings, setHoldings] = useState<Holding[]>([]);
  const [settlements, setSettlements] = useState<SettlementRecord[]>([]);

  const load = useCallback(async () => {
    if (!address) {
      setHoldings([]);
      setSettlements([]);
      return;
    }
    const res = await fetch(`/api/portfolio?investor=${address}`);
    if (res.ok) {
      const json = (await res.json()) as { holdings: Holding[]; settlements: SettlementRecord[] };
      setHoldings(json.holdings);
      setSettlements(json.settlements);
    }
  }, [address]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    const handler = () => void load();
    window.addEventListener("roughnet:settlement", handler);
    return () => window.removeEventListener("roughnet:settlement", handler);
  }, [load]);

  const usd = (v: string) => formatUnits(BigInt(v), STABLECOIN_DECIMALS);
  const short = (a: string) => `${a.slice(0, 6)}…${a.slice(-4)}`;

  return (
    <section className="panel">
      <h2 style={{ margin: 0 }}>Your portfolio</h2>

      {!isConnected ? (
        <p className="muted">Connect your wallet to see holdings and settlement history.</p>
      ) : (
        <>
          <h3>Holdings &amp; cost basis</h3>
          {holdings.length === 0 ? (
            <p className="muted">No holdings yet — subscribe to a primary offering above.</p>
          ) : (
            <ul className="records">
              {holdings.map((h) => (
                <li key={h.token}>
                  <code>{short(h.token)}</code> · <strong>{h.quantity}</strong> fractions · cost{" "}
                  {usd(h.totalCost)} mUSD · basis {usd(h.avgUnitCost)} mUSD/fraction
                </li>
              ))}
            </ul>
          )}

          <h3>Settlement history</h3>
          {settlements.length === 0 ? (
            <p className="muted">No settlements yet.</p>
          ) : (
            <ul className="records">
              {settlements.map((s) => (
                <li key={s.id}>
                  Bought <strong>{s.quantity}</strong> of <code>{short(s.token)}</code> for{" "}
