14	import { IIdentity } from "@onchain-id/solidity/contracts/interface/IIdentity.sol";
15	
16	/// @notice Minimal view of the AgentRole on the concrete ERC-3643 token (not exposed by IToken).
17	interface ITokenAgent {
18	    function addAgent(address agent) external;
19	}
20	
21	/// @notice Acceptance tests for issue #3 — primary subscription & atomic DvP settlement (Epic 4).
22	///         Runs against a real ERC-3643 suite (only the off-chain KYC decision is mocked, as in
23	///         issue #2) so the compliance-gated delivery leg is exercised for real.
24	contract PrimaryOfferingTest is Test, TREXSuiteDeployer {
25	    Suite internal suite;
26	    IToken internal token;
27	    IIdentityRegistry internal ir;
28	    MockStablecoin internal usd;
29	    PrimaryOffering internal offering;
30	
31	    uint256 internal constant ISSUER_PK = 0xA11CE;
32	    address internal issuer;
33	
34	    address internal vendor = address(0x5EED);
35	    address internal feeRecipient = address(0xFEE5);
36	
37	    uint256 internal constant ALICE_PK = 0xA1;
38	    uint256 internal constant BOB_PK = 0xB0B;
39	    uint256 internal constant CAROL_PK = 0xCA401;
40	    address internal alice; // whitelisted subscriber
41	    address internal bob; // whitelisted subscriber
42	    address internal carol; // never passes KYC
43	
44	    // 6-decimal stablecoin; token has 0 decimals (whole fractions).
45	    uint256 internal constant UNIT = 1e6;
46	    uint256 internal constant PRICE = 100 * UNIT; // 100 mUSD per fraction
47	
48	    // Mirror of PrimaryOffering.Subscribed for vm.expectEmit (0.8.17 has no Contract.Event refs).
49	    event Subscribed(
50	        uint256 indexed offeringId,
51	        address indexed investor,
52	        uint256 quantity,
53	        uint256 netToVendor,
54	        uint256 fee,
55	        uint256 totalPaid
56	    );
57	
58	    function setUp() public {
59	        issuer = vm.addr(ISSUER_PK);
60	        suite = _deployFullSuite(address(this), address(this), issuer);
61	        token = IToken(suite.token);
62	        ir = IIdentityRegistry(suite.identityRegistry);
63	        token.unpause();
64	
65	        alice = _provision("alice", ALICE_PK);
66	        bob = _provision("bob", BOB_PK);
67	        carol = vm.addr(CAROL_PK);
68	
69	        usd = new MockStablecoin();
70	        offering = new PrimaryOffering(usd);
71	
72	        // Grant the offering the token agent role so it can mint the delivery leg.
73	        ITokenAgent(suite.token).addAgent(address(offering));
74	
75	        // Fund subscribers with mock stablecoin (simulated on-ramp) and approve the offering.
76	        usd.mint(alice, 1_000_000 * UNIT);
77	        usd.mint(bob, 1_000_000 * UNIT);
78	        vm.prank(alice);
79	        usd.approve(address(offering), type(uint256).max);
80	        vm.prank(bob);
81	        usd.approve(address(offering), type(uint256).max);
82	    }
83	
84	    function _provision(string memory label, uint256 walletPk) internal returns (address wallet) {
85	        wallet = vm.addr(walletPk);
86	        address identity = IIdFactory(suite.idFactory).createIdentity(wallet, label);
87	        bytes memory data = abi.encode(label, "KYC:ok");
88	        bytes32 dataHash = keccak256(abi.encode(identity, KYC_TOPIC, data));
89	        bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
90	        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);
91	        vm.prank(wallet);
92	        IIdentity(identity)
93	            .addClaim(KYC_TOPIC, 1, suite.claimIssuer, abi.encodePacked(r, s, v), data, "");
94	        ir.registerIdentity(wallet, IIdentity(identity), 840);
95	    }
96	
97	    /// Create a vanilla offering (no discount, no fee) with the given caps.
98	    function _createPlain(uint256 cap, uint256 perInvestorLimit) internal returns (uint256 id) {
99	        id = offering.createOffering(token, vendor, PRICE, 0, 0, address(0), cap, perInvestorLimit);
100	    }
101	
102	    // --- DvP happy path -----------------------------------------------------
103	
104	    function test_subscribe_atomicDvp_movesTokensAndCash() public {
105	        uint256 id = _createPlain(1_000, 0);
106	
107	        uint256 qty = 10;
108	        uint256 cost = qty * PRICE;
109	
110	        vm.expectEmit(true, true, false, true, address(offering));
111	        emit Subscribed(id, alice, qty, cost, 0, cost);
112	
113	        vm.prank(alice);
114	        offering.subscribe(id, qty);
115	
116	        assertEq(token.balanceOf(alice), qty, "fractions delivered");
117	        assertEq(usd.balanceOf(vendor), cost, "vendor received proceeds");
118	        assertEq(usd.balanceOf(alice), 1_000_000 * UNIT - cost, "subscriber debited");
119	        assertEq(offering.purchased(id, alice), qty);
120	        assertEq(offering.remaining(id), 990);
121	    }
122	
123	    function test_subscribe_quoteMatchesCharge() public {
124	        uint256 id =
125	            offering.createOffering(token, vendor, PRICE, 1_000, 250, feeRecipient, 1_000, 0);
126	        uint256 qty = 4;
127	
128	        // 1000 bps discount = 10% off; 250 bps fee on the net.
129	        uint256 gross = qty * PRICE;
130	        uint256 net = gross - (gross * 1_000) / 10_000;
131	        uint256 fee = (net * 250) / 10_000;
132	        uint256 total = net + fee;
133	
134	        (uint256 qNet, uint256 qFee, uint256 qTotal) = offering.quote(id, qty);
135	        assertEq(qNet, net);
136	        assertEq(qFee, fee);
137	        assertEq(qTotal, total);
138	
139	        vm.prank(alice);
140	        offering.subscribe(id, qty);
141	
142	        assertEq(usd.balanceOf(vendor), net, "vendor gets discounted net");
143	        assertEq(usd.balanceOf(feeRecipient), fee, "platform gets fee");
144	        assertEq(usd.balanceOf(alice), 1_000_000 * UNIT - total, "subscriber pays net+fee");
145	        assertEq(token.balanceOf(alice), qty);
146	    }
147	
148	    // --- Atomicity / reverts ------------------------------------------------
149	
150	    function test_subscribe_nonWhitelisted_revertsAndMovesNothing() public {
151	        uint256 id = _createPlain(1_000, 0);
152	        usd.mint(carol, 1_000_000 * UNIT);
153	        vm.prank(carol);
154	        usd.approve(address(offering), type(uint256).max);
155	
156	        uint256 vendorBefore = usd.balanceOf(vendor);
157	        uint256 carolBefore = usd.balanceOf(carol);
158	
159	        // Delivery leg (mint to unverified carol) reverts -> whole DvP unwinds, cash untouched.
160	        vm.prank(carol);
161	        vm.expectRevert("Identity is not verified.");
162	        offering.subscribe(id, 5);
163	
164	        assertEq(usd.balanceOf(vendor), vendorBefore, "vendor not paid on revert");
165	        assertEq(usd.balanceOf(carol), carolBefore, "subscriber not debited on revert");
166	        assertEq(token.balanceOf(carol), 0);
167	        assertEq(offering.purchased(id, carol), 0);
168	    }
169	
170	    function test_subscribe_insufficientBalance_revertsAtomically() public {
171	        uint256 id = _createPlain(1_000, 0);
172	        address poor = _provision("poor", 0xDEAD);
173	        vm.prank(poor);
174	        usd.approve(address(offering), type(uint256).max);
175	        // poor has zero stablecoin.
176	
177	        vm.prank(poor);
178	        vm.expectRevert();
179	        offering.subscribe(id, 1);
180	
181	        assertEq(token.balanceOf(poor), 0, "no fractions without payment");
182	        assertEq(offering.purchased(id, poor), 0);
183	    }
184	
