  {
    type: "function",
    name: "getOffering",
    inputs: [{ name: "offeringId", type: "uint256" }],
    outputs: [
      {
        type: "tuple",
        components: [
          { name: "token", type: "address" },
          { name: "vendor", type: "address" },
          { name: "unitPrice", type: "uint256" },
          { name: "discountBps", type: "uint16" },
          { name: "feeBps", type: "uint16" },
