import type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";
import type {
  NewSettlementRecord,
  SettlementRecord,
  SettlementsRepository,
} from "./settlements";

/**
 * In-memory fallback used in tests and for local dev when no DATABASE_URL is set.
 * Implements the same contract as the Neon-backed repository.
 */
export class InMemoryRecordsRepository implements RecordsRepository {
  private records: RegistryRecord[] = [];
  private nextId = 1;

  async add(record: NewRegistryRecord): Promise<RegistryRecord> {
    const saved: RegistryRecord = {
      id: this.nextId++,
      createdAt: new Date().toISOString(),
      ...record,
    };
    this.records.push(saved);
    return saved;
  }

  async list(limit = 50): Promise<RegistryRecord[]> {
    return [...this.records].reverse().slice(0, limit);
  }
}

/**
 * In-memory fallback for the primary-subscription settlement read-model. Same contract as the
 * Neon-backed repository; used in tests and local dev when no DATABASE_URL is set.
 */
export class InMemorySettlementsRepository implements SettlementsRepository {
  private records: SettlementRecord[] = [];
  private nextId = 1;

  async add(record: NewSettlementRecord): Promise<SettlementRecord> {
    const saved: SettlementRecord = {
      id: this.nextId++,
      createdAt: new Date().toISOString(),
      ...record,
      investor: record.investor.toLowerCase(),
    };
    this.records.push(saved);
    return saved;
  }

  async list(investor?: string, limit = 100): Promise<SettlementRecord[]> {
    const wanted = investor?.toLowerCase();
    return [...this.records]
      .reverse()
      .filter((r) => (wanted ? r.investor === wanted : true))
      .slice(0, limit);
  }
}

