import { neon } from "@neondatabase/serverless";
import type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";
import type {
  NewSettlementRecord,
  SettlementRecord,
  SettlementsRepository,
} from "./settlements";

type Sql = ReturnType<typeof neon>;

interface RawRow {
  id: number | string;
  chain_id: number | string;
  note: string;
  tx_hash: string;
  updated_by: string;
  created_at: string | Date;
}

const toRecord = (row: RawRow): RegistryRecord => ({
  id: Number(row.id),
  chainId: Number(row.chain_id),
  note: row.note,
  txHash: row.tx_hash,
  updatedBy: row.updated_by,
  createdAt: new Date(row.created_at).toISOString(),
});

/**
 * Neon (serverless Postgres) implementation of {@link RecordsRepository}.
 * Lazily ensures the table exists so the walking-skeleton demo works against a
 * fresh database; in a fuller build this moves to an explicit migration step.
 */
export class NeonRecordsRepository implements RecordsRepository {
  private readonly sql: Sql;
  private ready: Promise<void> | undefined;

  constructor(connectionString: string) {
    this.sql = neon(connectionString);
  }

  private ensureSchema(): Promise<void> {
    this.ready ??= (async () => {
      await this.sql`
        CREATE TABLE IF NOT EXISTS registry_records (
          id          BIGSERIAL PRIMARY KEY,
          chain_id    BIGINT      NOT NULL,
          note        TEXT        NOT NULL,
          tx_hash     TEXT        NOT NULL,
          updated_by  TEXT        NOT NULL,
          created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
        )
      `;
    })();
    return this.ready;
  }

  async add(record: NewRegistryRecord): Promise<RegistryRecord> {
    await this.ensureSchema();
    const rows = (await this.sql`
      INSERT INTO registry_records (chain_id, note, tx_hash, updated_by)
      VALUES (${record.chainId}, ${record.note}, ${record.txHash}, ${record.updatedBy})
      RETURNING id, chain_id, note, tx_hash, updated_by, created_at
    `) as RawRow[];
    return toRecord(rows[0]!);
  }

  async list(limit = 50): Promise<RegistryRecord[]> {
    await this.ensureSchema();
    const rows = (await this.sql`
      SELECT id, chain_id, note, tx_hash, updated_by, created_at
      FROM registry_records
      ORDER BY id DESC
      LIMIT ${limit}
    `) as RawRow[];
    return rows.map(toRecord);
  }
}

interface RawSettlementRow {
  id: number | string;
  chain_id: number | string;
  offering_id: number | string;
  token: string;
  investor: string;
  vendor: string;
  quantity: string;
  net_to_vendor: string;
  fee: string;
  total_paid: string;
  tx_hash: string;
  created_at: string | Date;
}

const toSettlement = (row: RawSettlementRow): SettlementRecord => ({
  id: Number(row.id),
  chainId: Number(row.chain_id),
  offeringId: Number(row.offering_id),
  token: row.token,
  investor: row.investor,
  vendor: row.vendor,
  quantity: String(row.quantity),
  netToVendor: String(row.net_to_vendor),
  fee: String(row.fee),
  totalPaid: String(row.total_paid),
  txHash: row.tx_hash,
  createdAt: new Date(row.created_at).toISOString(),
});

/**
 * Neon (serverless Postgres) implementation of {@link SettlementsRepository}.
 * Amounts are NUMERIC(78,0) so 256-bit token/stablecoin values round-trip exactly; the driver
 * returns them as strings, which is what the read-model uses.
 */
export class NeonSettlementsRepository implements SettlementsRepository {
  private readonly sql: Sql;
  private ready: Promise<void> | undefined;

  constructor(connectionString: string) {
    this.sql = neon(connectionString);
  }

  private ensureSchema(): Promise<void> {
    this.ready ??= (async () => {
      await this.sql`
        CREATE TABLE IF NOT EXISTS subscription_settlements (
          id            BIGSERIAL PRIMARY KEY,
          chain_id      BIGINT        NOT NULL,
          offering_id   BIGINT        NOT NULL,
          token         TEXT          NOT NULL,
          investor      TEXT          NOT NULL,
          vendor        TEXT          NOT NULL,
          quantity      NUMERIC(78,0) NOT NULL,
          net_to_vendor NUMERIC(78,0) NOT NULL,
          fee           NUMERIC(78,0) NOT NULL,
          total_paid    NUMERIC(78,0) NOT NULL,
          tx_hash       TEXT          NOT NULL,
          created_at    TIMESTAMPTZ   NOT NULL DEFAULT now()
        )
      `;
      await this.sql`
        CREATE INDEX IF NOT EXISTS subscription_settlements_investor_idx
          ON subscription_settlements (investor)
      `;
    })();
    return this.ready;
  }

  async add(record: NewSettlementRecord): Promise<SettlementRecord> {
    await this.ensureSchema();
    const rows = (await this.sql`
      INSERT INTO subscription_settlements
        (chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee, total_paid, tx_hash)
      VALUES
        (${record.chainId}, ${record.offeringId}, ${record.token}, ${record.investor.toLowerCase()},
         ${record.vendor}, ${record.quantity}, ${record.netToVendor}, ${record.fee},
         ${record.totalPaid}, ${record.txHash})
      RETURNING id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
                total_paid, tx_hash, created_at
    `) as RawSettlementRow[];
    return toSettlement(rows[0]!);
  }

  async list(investor?: string, limit = 100): Promise<SettlementRecord[]> {
    await this.ensureSchema();
    const rows = (
      investor
        ? await this.sql`
            SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
                   total_paid, tx_hash, created_at
            FROM subscription_settlements
            WHERE investor = ${investor.toLowerCase()}
            ORDER BY id DESC
            LIMIT ${limit}
          `
        : await this.sql`
            SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
                   total_paid, tx_hash, created_at
            FROM subscription_settlements
            ORDER BY id DESC
            LIMIT ${limit}
          `
    ) as RawSettlementRow[];
    return rows.map(toSettlement);
  }
}

