import { describe, expect, it } from "vitest";
import { InMemorySettlementsRepository } from "./memory";
import type { NewSettlementRecord } from "./settlements";

const sample = (overrides: Partial<NewSettlementRecord> = {}): NewSettlementRecord => ({
  chainId: 11155111,
  offeringId: 0,
  token: "0x00000000000000000000000000000000000000aa",
  investor: "0x000000000000000000000000000000000000ABCD",
  vendor: "0x000000000000000000000000000000000000beef",
  quantity: "10",
  netToVendor: "1000000000",
  fee: "0",
  totalPaid: "1000000000",
  txHash: "0xabc",
  ...overrides,
});

describe("InMemorySettlementsRepository", () => {
  it("persists a settlement and lowercases the investor", async () => {
    const repo = new InMemorySettlementsRepository();

    const saved = await repo.add(sample());

    expect(saved.id).toBeGreaterThan(0);
    expect(saved.investor).toBe("0x000000000000000000000000000000000000abcd");
    expect(saved.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });

  it("returns settlements newest first", async () => {
    const repo = new InMemorySettlementsRepository();
    await repo.add(sample({ txHash: "0x1" }));
    await repo.add(sample({ txHash: "0x2" }));

    const all = await repo.list();
    expect(all.map((r) => r.txHash)).toEqual(["0x2", "0x1"]);
  });

  it("filters by investor case-insensitively", async () => {
    const repo = new InMemorySettlementsRepository();
    await repo.add(sample({ investor: "0xAAA0000000000000000000000000000000000001", txHash: "0xa" }));
    await repo.add(sample({ investor: "0xBBB0000000000000000000000000000000000002", txHash: "0xb" }));

    const mine = await repo.list("0xaaa0000000000000000000000000000000000001");
    expect(mine).toHaveLength(1);
    expect(mine[0]!.txHash).toBe("0xa");
  });

  it("respects the limit argument", async () => {
    const repo = new InMemorySettlementsRepository();
    await repo.add(sample({ txHash: "0x1" }));
    await repo.add(sample({ txHash: "0x2" }));
    await repo.add(sample({ txHash: "0x3" }));

    const limited = await repo.list(undefined, 2);
    expect(limited.map((r) => r.txHash)).toEqual(["0x3", "0x2"]);
  });
});

