import "server-only";
import { createPublicClient, http, parseEventLogs, type Hex } from "viem";
import { base, polygon, sepolia } from "viem/chains";
import { getChain } from "@/lib/chains";
import { getRegistryAddress, registryAbi } from "@/lib/contract";
import type { NewRegistryRecord } from "@/lib/db/repository";

/**
 * Trust boundary for the Register read-model, mirroring {@link verifySettlement}. The
 * /api/records POST is public, so rather than trust client-supplied `note`/`updatedBy`, this
 * re-derives the record from the on-chain `NoteUpdated` event: it loads the receipt, confirms it
 * succeeded, and decodes the event emitted by the configured RoughNetRegistry. Only on-chain
 * truth is persisted; the client cannot forge or spam register rows.
 */

const RPC_URL: Record<number, string | undefined> = {
  [sepolia.id]: process.env.NEXT_PUBLIC_SEPOLIA_RPC_URL,
  [polygon.id]: process.env.NEXT_PUBLIC_POLYGON_RPC_URL,
  [base.id]: process.env.NEXT_PUBLIC_BASE_RPC_URL,
  31337: "http://127.0.0.1:8545",
};

export interface NoteClaim {
  chainId: number;
  txHash: Hex;
}

/** Thrown when the claimed note update cannot be verified against the chain (route → 422). */
export class RecordVerificationError extends Error {}
/** Thrown for configuration problems (registry not wired for the chain) (route → 501). */
export class RecordNotConfiguredError extends Error {}

export async function verifyNoteUpdate(claim: NoteClaim): Promise<NewRegistryRecord> {
  const address = getRegistryAddress(claim.chainId);
  if (!address) {
    throw new RecordNotConfiguredError(`No registry configured for chain ${claim.chainId}.`);
  }
  const chain = getChain(claim.chainId);
  if (!chain) {
    throw new RecordNotConfiguredError(`Unsupported chain ${claim.chainId}.`);
  }

  const client = createPublicClient({ chain, transport: http(RPC_URL[claim.chainId]) });

  let receipt;
  try {
    receipt = await client.getTransactionReceipt({ hash: claim.txHash });
  } catch {
    throw new RecordVerificationError("Transaction not found.");
  }
  if (receipt.status !== "success") {
    throw new RecordVerificationError("Transaction did not succeed.");
  }

  const events = parseEventLogs({
    abi: registryAbi,
    eventName: "NoteUpdated",
    logs: receipt.logs,
  }).filter((log) => log.address.toLowerCase() === address.toLowerCase());

  const event = events[0];
  if (!event) {
    throw new RecordVerificationError("No NoteUpdated event from the registry in the transaction.");
  }

  return {
    chainId: claim.chainId,
    note: event.args.note,
    txHash: claim.txHash,
    updatedBy: event.args.by,
  };
}

